import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { defineConfig, run, createAdmissionGraph } from '../../src/index.ts';
import { validatePreparedTaskGraph } from '../../src/project-run/task-scheduler/graph-validation.ts';
import { applyAdmission } from '../../src/project-run/task-scheduler/scheduler-task-lifecycle.ts';
import { parseCheckTreeAuthoring } from '../../src/project-definition/check-tree/authoring.ts';
const outputs={machinePublication:{enabled:false},progressRendering:{enabled:false},diagnosticLogging:{enabled:false}} as const;
const graphCounts=[16,32,64,128].map(size=>{
  const tasks=Array.from({length:size},(_,i)=>({id:`task-${i}`,admissionPriority:0,dependsOn:i?[`task-${i-1}`]:[],observes:[],mutex:[],resourceClaims:[],scopeId:'scope'}));
  let gets=0;
  class CountingMap extends Map<string,typeof tasks[number]>{override get(key:string){gets++;return super.get(key);}}
  const scopes=[{id:'scope',maxParallel:1,activationTaskIds:['task-0'],terminalTaskId:`task-${size-1}`}];
  validatePreparedTaskGraph({tasks,taskById:new CountingMap(tasks.map(t=>[t.id,t])),scopes,scopeById:new Map(scopes.map(s=>[s.id,s])),resourceCapacities:[],rootMaxParallel:1});
  assert.equal(gets,size*(size+1)/2+1);
  const api=createAdmissionGraph({maxParallel:1,graph:{tasks:tasks.map(({id,...t})=>({...t,taskId:id})),scopes,resourceCapacities:[]}});
  assert.equal(api.initialState().inspection.nextBoundary,"select");
  return {size,mapGetCount:gets,expected:size*(size+1)/2+1,publicConstructionSucceeded:true};
});
const dagCounts=[];
for(const depth of [3,5,7,9]){
  let ownKeys=0,executeCalls=0;
  const counted=<T extends object>(value:T):T=>new Proxy(value,{ownKeys(target){ownKeys++;return Reflect.ownKeys(target);}});
  let value:any=counted({checkId:'leaf',displayName:'leaf',execute:()=>{executeCalls++;return {status:'passed',data:{}};}});
  for(let i=0;i<depth;i++)value=counted({checkId:`level-${i}`,displayName:'container',checks:[value,value]});
  const result=await run(defineConfig({checks:[value],scheduler:{maxParallel:1},outputs}));
  assert.equal(ownKeys,2**(depth+1)-1);assert.equal(result.kind,'planning');assert.equal(executeCalls,0);
  dagCounts.push({depth,uniqueInputCheckObjects:depth+1,ownKeys,expected:2**(depth+1)-1,resultKind:result.kind,executeCalls});
}
const pendingCounts=[];
for(const size of [16,32,64,128]){
  const pending=Array.from({length:size},(_,i)=>({id:`task-${i}`}));let comparisons=0;
  const original=pending.findIndex;
  pending.findIndex=function(predicate:any,thisArg?:unknown){return original.call(this,(...args:any[])=>{comparisons++;return predicate.apply(thisArg,args);});};
  const state:any={pending,runningById:new Map(),execute:()=>true,admissionFacts:undefined};
  for(let i=size-1;i>=0;i--)applyAdmission(state,{kind:'admit',taskId:`task-${i}`} as any);
  await Promise.all([...state.runningById.values()].map((item:any)=>item.completion));
  assert.equal(comparisons,size*(size+1)/2);
  pendingCounts.push({size,findIndexPredicateCalls:comparisons,expected:size*(size+1)/2,boundary:'actual applyAdmission with minimal private Shell state; public reverse-policy reachability checked separately'});
}
const publicReverse=[];
for(const size of [16,32]){
 const order:string[]=[];
 const result=await run(defineConfig({checks:Array.from({length:size},(_,i)=>({checkId:`task-${i}`,displayName:`task-${i}`,execute:()=>{order.push(`task-${i}`);return {status:'passed',data:{}};}})),outputs,scheduler:{maxParallel:1,admissionPolicy:{kind:'custom',strategy:{kind:'simple',decide:(context:any)=>{const last=context.candidates.at(-1);return last?.canAdmit?{kind:'select',taskId:last.taskId}:{kind:'wait'};}}}}}));
 assert.equal(result.kind,'completed');assert.deepEqual(order,Array.from({length:size},(_,i)=>`task-${size-i-1}`));publicReverse.push({size,resultKind:result.kind,order});
}
const result={capturedAt:new Date().toISOString(),runtime:process.versions,method:'deterministic small operation counts, not timings/heap; current source; no Product modifications',graphCounts,dagCounts,pendingCounts,publicReverse};
writeFileSync('/workspace/vibe-check/tmp/complexity-investigation-20261015/operation-counts.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));

import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { inherit } from '../../src/index.ts';
import { resolveCheckTree } from '../../src/project-definition/check-tree/resolution.ts';
import { nextRunningSettlement } from '../../src/project-run/task-scheduler/scheduler-task-lifecycle.ts';
const inheritance=[];
for(const size of [16,32,64,128]){
  let value:any={checkId:'leaf',displayName:'leaf',execute:()=>({status:'passed',data:{}})};
  for(let i=0;i<size;i++) value={checkId:`parent-${i}`,displayName:'parent',mutex:inherit({add:[`mutex-${i}`]}),checks:[value]};
  const original=Array.prototype.filter;let visitedSlots=0;
  Array.prototype.filter=function(predicate:any,thisArg?:unknown){if(this.length>0&&this.every(v=>typeof v==='string'&&v.startsWith('mutex-')))visitedSlots+=this.length;return Reflect.apply(original,this,[predicate,thisArg]);};
  let tree;
  try {tree=resolveCheckTree([value],1);} finally {Array.prototype.filter=original;}
  assert.equal(visitedSlots,size*(size-1)/2);assert.equal(tree?.leaves.length,1);assert.equal(tree?.leaves[0]?.mutex.length,size);
  inheritance.push({size,filterVisitedSlots:visitedSlots,expected:size*(size-1)/2,leafCount:tree.leaves.length,finalMutexCount:tree.leaves[0].mutex.length});
}
const races=[];
for(const size of [16,32,64,128]){
 const runningById=new Map(Array.from({length:size},(_,i)=>[`task-${i}`,{completion:Promise.resolve({taskId:`task-${i}`,settlement:{kind:'completed',value:true}})}]));
 const original=Promise.race;let raceInputs=0;
 Promise.race=function(values:any){raceInputs+=values.length;return Reflect.apply(original,this,[values]);};
 try {while(runningById.size>0){const completion=await nextRunningSettlement({runningById} as any);runningById.delete(completion.taskId);}} finally {Promise.race=original;}
 assert.equal(raceInputs,size*(size+1)/2);races.push({size,raceInputs,expected:size*(size+1)/2,boundary:'actual private nextRunningSettlement with resolved promises; does not measure retained reactions/heap'});
}
const result={capturedAt:new Date().toISOString(),runtime:process.versions,method:'small deterministic counts of actual current private helpers; no timings or heap',inheritance,races};writeFileSync('/workspace/vibe-check/tmp/complexity-investigation-20261015/secondary-operation-counts.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));

// Audit-only operation counts. Run in a disposable process under external hard timeout.
// Patches are restored in finally; no production source, fixtures, tests or metrics policy changed.
import { analyzeLizardSource } from '../../src/package-checks/function-metrics/analyzer/port-facade.ts';
import { FunctionInfo } from '../../src/package-checks/function-metrics/analyzer/analysis-model.ts';
import { NestingStack } from '../../src/package-checks/function-metrics/analyzer/analysis-context.ts';
import { CodeStateMachine } from '../../src/package-checks/function-metrics/analyzer/shared/code-reader.ts';
import { RubyReader } from '../../src/package-checks/function-metrics/analyzer/readers/ruby.ts';
const observations: unknown[] = [];
const oldAdd = FunctionInfo.prototype.addToLongName;
const oldConsume = CodeStateMachine.prototype.consume;
const oldNamespace = NestingStack.prototype.withNamespace;
const oldExec = RegExp.prototype.exec;
let longCalls = 0, longCharacters = 0, consumeCalls = 0, namespaceCalls = 0, namespaceSlots = 0;
let quotedMatches = 0, quotedMatchedCharacters = 0;
FunctionInfo.prototype.addToLongName = function (s: string) {
  longCalls++; longCharacters += this.longName.length;
  return oldAdd.call(this, s);
};
CodeStateMachine.prototype.consume = function (s: string) { consumeCalls++; return oldConsume.call(this, s); };
NestingStack.prototype.withNamespace = function (s: string) {
  namespaceCalls++; namespaceSlots += this.nesting_stack.length; return oldNamespace.call(this, s);
};
RegExp.prototype.exec = function (s: string) {
  const m = oldExec.call(this, s);
  if (this.global && this.source.includes('0x') && m?.[0].startsWith('"') && m[0].includes('#{')) {
    quotedMatches++; quotedMatchedCharacters += m[0].length;
  }
  return m;
};
function analyze(label: string, n: number, filename: string, sourceCode: string) {
  longCalls = longCharacters = consumeCalls = namespaceCalls = namespaceSlots = 0;
  const result = analyzeLizardSource({ filename, sourceCode });
  observations.push({ label, n, bytes: Buffer.byteLength(sourceCode), functionCount: result?.function_list.length,
    parameterCounts: result?.function_list.map(f=>f.parameter_count), longCalls, longCharacters, consumeCalls, namespaceCalls, namespaceSlots });
}
try {
  for (const n of [16, 32, 64, 128]) {
    analyze('long-python-signature', n, 'audit.py', `def f(${Array.from({length:n}, (_,i)=>'a'+i).join(',')}):\n pass\n`);
    analyze('python-fixed-token-default', n, 'audit.py', `def f(a=${Array(n).fill('1').join('+')}):\n pass\n`);
    analyze('nested-go-blocks', n, 'audit.go', `package main\nfunc f(){${'{'.repeat(n)}${'_ = 1;'.repeat(n)}${'}'.repeat(n)}}`);
    analyze('nested-ts-parentheses', n, 'audit.ts', `const x = ${'('.repeat(n)}1${')'.repeat(n)};`);
    analyze('nested-cpp-no-functions', n, 'audit.cpp', `${'namespace a {'.repeat(n)}${'extern int x;'.repeat(n)}${'}'.repeat(n)}`);
    quotedMatches = quotedMatchedCharacters = 0;
    const source = `x = "${'#{1}'.repeat(n)}"`;
    const tokens = [...RubyReader.generateTokens(source)];
    observations.push({label:'ruby-flat-interpolations',n,bytes:Buffer.byteLength(source),tokens:tokens.length,quotedMatches,quotedMatchedCharacters});
  }
  analyze('legal-cpp-array-parameter', 64, 'audit.cpp', `void f(int ${'a'.repeat(64)}[]) {}`);
  console.log(JSON.stringify({ runtime: process.versions, method:'instrumented production operations; no wall-time measurements', observations }, null, 2));
} finally {
 FunctionInfo.prototype.addToLongName = oldAdd; CodeStateMachine.prototype.consume = oldConsume;
 NestingStack.prototype.withNamespace = oldNamespace; RegExp.prototype.exec = oldExec;
}
